'use strict';

// MODULES //

var tape = require( 'tape' );
var trunc = require( '@stdlib/math-base-special-trunc' );
var randu = require( '@stdlib/random-base-randu' );
var PINF = require( '@stdlib/constants-float64-pinf' );
var NINF = require( '@stdlib/constants-float64-ninf' );
var isInteger = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof isInteger, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `true` if provided an integer', function test( t ) {
	var i;
	for ( i = -50; i < 51; i++ ) {
		t.strictEqual( isInteger( i ), true, 'returns expected value when provided '+i );
	}
	t.end();
});

tape( 'the function returns `false` if not provided an integer', function test( t ) {
	var v;
	var i;
	for ( i = 0; i < 100; i++ ) {
		v = ( randu()*100.0 ) - 50.0;
		if ( trunc(v) !== v ) {
			t.strictEqual( isInteger( v ), false, 'returns expected value when provided '+v );
		}
	}
	t.end();
});

tape( 'the function returns `false` if provided `NaN`', function test( t ) {
	t.strictEqual( isInteger( NaN ), false, 'returns expected value' );
	t.end();
});

tape( 'WARNING: function returns `true` if provided `+infinity`', function test( t ) {
	t.strictEqual( isInteger( PINF ), true, 'returns expected value' );
	t.end();
});

tape( 'WARNING: function returns `true` if provided `-infinity`', function test( t ) {
	t.strictEqual( isInteger( NINF ), true, 'returns expected value' );
	t.end();
});","lineStart":1,"lineEnd":72,"totalLines":72,"truncated":false}},"title":"repos\pc-lib-3456\math-base-assert-is-integer\test\test.js","time":{"start":1783769002374,"end":1783769002413}},"id":"prt_f50eaeb8c001pbe9zNG68if1SO","sessionID":"ses_0af164bb7ffelOEcxzlBjA0zR7","messageID":"msg_f50eab6ed0017IH92ZNiHGsz7c"}}

